def open_for_finance(apps, schema_editor):
    """Costs by occupier are for finance (and administrators); the standard Finance area opens them, with the
    space pages they sit on."""
    AccessArea = apps.get_model("core", "AccessArea")
    for area in AccessArea.objects.filter(code="finance"):
        missing = [m for m in ("space", "spacecosts") if m not in (area.modules or [])]
        if missing:
            area.modules = [*(area.modules or []), *missing]
            area.save(update_fields=["modules"])


